import React, { useState } from "react";

const API_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";

export default function RepoInput({ onJobStarted }) {
  const [repoUrl, setRepoUrl] = useState("");
  const [instruction, setInstruction] = useState("Convert JavaScript to TypeScript");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);

  async function handleSubmit() {
    setError(null);

    if (!repoUrl.includes("github.com")) {
      setError("Please paste a valid GitHub repo URL.");
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch(`${API_URL}/api/repo/analyze`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ repoUrl, instruction }),
      });

      const data = await res.json();
      if (!res.ok) {
        setError(data.error || "Something went wrong queuing the job.");
        return;
      }

      onJobStarted(data.jobId, repoUrl);
    } catch (err) {
      setError("Could not reach the backend. Is it running on port 5000?");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="w-full max-w-2xl mx-auto bg-terminal-bg border border-terminal-border rounded-lg p-6 font-mono">
      <h1 className="text-terminal-accent text-xl mb-4">⚡ CodeCatalyst</h1>

      <label className="block text-terminal-text text-sm mb-1">GitHub repo URL</label>
      <input
        type="text"
        value={repoUrl}
        onChange={(e) => setRepoUrl(e.target.value)}
        placeholder="https://github.com/owner/repo"
        className="w-full mb-4 px-3 py-2 bg-black border border-terminal-border rounded text-terminal-text focus:outline-none focus:border-terminal-accent"
      />

      <label className="block text-terminal-text text-sm mb-1">Instruction</label>
      <input
        type="text"
        value={instruction}
        onChange={(e) => setInstruction(e.target.value)}
        className="w-full mb-4 px-3 py-2 bg-black border border-terminal-border rounded text-terminal-text focus:outline-none focus:border-terminal-accent"
      />

      {error && <p className="text-terminal-red text-sm mb-3">{error}</p>}

      <button
        onClick={handleSubmit}
        disabled={submitting}
        className="w-full py-2 rounded bg-terminal-accent text-black font-semibold disabled:opacity-50"
      >
        {submitting ? "Queuing..." : "Analyze Repo"}
      </button>
    </div>
  );
}
